 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null){selected=data.getData();setStatus("Bestand gekozen. Tik op een apparaat om te versturen.");}}
 void render(){runOnUiThread(()->{list.removeAllViews();if(devices.isEmpty()){TextView t=text("Nog geen apparaten gevonden",14);t.setTextColor(0xff999999);list.addView(t);}else for(String name:devices.keySet()){Button b=new Button(this);b.setText("📱   "+name+"    →");b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(rounded(0xff202024,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(58));lp.bottomMargin=dp(8);list.addView(b,lp);b.setOnClickListener(v->send(name));}});}
 void startServer(){io.execute(()->{try{server=new ServerSocket(0);register(server.getLocalPort());while(!server.isClosed()){Socket s=server.accept();io.execute(()->receive(s));}}catch(Exception e){setStatus("Ontvangstserver: "+e.getMessage());}});}
 void register(int port){NsdServiceInfo info=new NsdServiceInfo();info.setServiceName(deviceName);info.setServiceType(serviceType);info.setPort(port);registration=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo i){}public void onRegistrationFailed(NsdServiceInfo i,int e){setStatus("Registratie mislukt: "+e);}public void onServiceUnregistered(NsdServiceInfo i){}public void onUnregistrationFailed(NsdServiceInfo i,int e){}};runOnUiThread(()->nsd.registerService(info,NsdManager.PROTOCOL_DNS_SD,registration));}
 void discover(){discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){}public void onStartDiscoveryFailed(String t,int e){setStatus("Zoeken mislukt: "+e);}public void onStopDiscoveryFailed(String t,int e){}public void onDiscoveryStopped(String t){}public void onServiceFound(NsdServiceInfo s){if(s.getServiceName().equals(deviceName))return;nsd.resolveService(s,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo x,int e){}public void onServiceResolved(NsdServiceInfo x){if(x.getHost()!=null){devices.put(x.getServiceName(),new InetSocketAddress(x.getHost(),x.getPort()));render();}}});}public void onServiceLost(NsdServiceInfo s){devices.remove(s.getServiceName());render();}};nsd.discoverServices(serviceType,NsdManager.PROTOCOL_DNS_SD,discovery);}
 void send(String name){if(selected==null){setStatus("Kies eerst een bestand.");return;}InetSocketAddress address=devices.get(name);if(address==null)return;io.execute(()->{try(Socket socket=new Socket()){socket.connect(address,6000);socket.setSoTimeout(60000);DataOutputStream out=new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));DataInputStream in=new DataInputStream(socket.getInputStream());String filename="bestand";android.database.Cursor c=getContentResolver().query(selected,null,null,null,null);if(c!=null){try{if(c.moveToFirst()){int col=c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(col>=0)filename=c.getString(col);}}finally{c.close();}}long size=-1;try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(selected,"r")){if(fd!=null)size=fd.getStatSize();}if(size<0||size>1024L*1024*1024){setStatus("Bestandsgrootte onbekend of te groot.");return;}out.writeUTF("AIRFLOW1");out.writeUTF(filename);out.writeLong(size);out.flush();if(!in.readBoolean()){setStatus("Ontvanger heeft geweigerd.");return;}try(InputStream file=getContentResolver().openInputStream(selected)){byte[] buffer=new byte[32768];int n;long sent=0;while((n=file.read(buffer))!=-1){out.write(buffer,0,n);sent+=n;}out.flush();if(sent!=size)throw new IOException("Bestandsgrootte gewijzigd");}setStatus("Bestand verstuurd naar "+name);}catch(Exception e){setStatus("Versturen mislukt: "+e.getMessage());}});}
 void receive(Socket socket){try{socket.setSoTimeout(60000);DataInputStream in=new DataInputStream(new BufferedInputStream(socket.getInputStream()));DataOutputStream out=new DataOutputStream(socket.getOutputStream());if(!"AIRFLOW1".equals(in.readUTF())){socket.close();return;}String filename=in.readUTF();long size=in.readLong();if(size<0||size>1024L*1024*1024){socket.close();return;}runOnUiThread(()->new AlertDialog.Builder(this).setTitle("AirFlow").setMessage("Bestand ontvangen?\n"+filename+" ("+(size/1024)+" KB)").setNegativeButton("Weiger",(d,w)->{try{out.writeBoolean(false);out.flush();socket.close();}catch(Exception ignored){}}).setPositiveButton("Accepteer",(d,w)->io.execute(()->{try{out.writeBoolean(true);out.flush();String safeName=new File(filename).getName().replaceAll("[\\\\/:*?\"<>|]","_");if(safeName.isEmpty())safeName="AirFlow-bestand";String extension="";int dot=safeName.lastIndexOf('.');if(dot>=0)extension=safeName.substring(dot+1).toLowerCase(java.util.Locale.ROOT);String mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(extension);if(mime==null)mime="application/octet-stream";boolean photo=mime.startsWith("image/"),video=mime.startsWith("video/");String folder=photo?Environment.DIRECTORY_PICTURES+"/AirFlow":video?Environment.DIRECTORY_MOVIES+"/AirFlow":Environment.DIRECTORY_DOWNLOADS+"/AirFlow";Uri collection=photo?MediaStore.Images.Media.EXTERNAL_CONTENT_URI:video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Downloads.EXTERNAL_CONTENT_URI;ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,safeName);values.put(MediaStore.MediaColumns.MIME_TYPE,mime);values.put(MediaStore.MediaColumns.RELATIVE_PATH,folder);values.put(MediaStore.MediaColumns.IS_PENDING,1);Uri destination=getContentResolver().insert(collection,values);if(destination==null)throw new IOException("Kan opslaglocatie niet maken");boolean complete=false;try{try(OutputStream file=getContentResolver().openOutputStream(destination)){if(file==null)throw new IOException("Opslag niet beschikbaar");byte[] buffer=new byte[32768];long remaining=size;while(remaining>0){int n=in.read(buffer,0,(int)Math.min(buffer.length,remaining));if(n<0)throw new EOFException();file.write(buffer,0,n);remaining-=n;}}ContentValues ready=new ContentValues();ready.put(MediaStore.MediaColumns.IS_PENDING,0);getContentResolver().update(destination,ready,null,null);complete=true;}finally{if(!complete)getContentResolver().delete(destination,null,null);}setStatus("Ontvangen: "+safeName+(photo||video?" · opgeslagen in Galerij (AirFlow)":" · opgeslagen in Downloads/AirFlow"));}catch(Exception e){setStatus("Ontvangst mislukt: "+e.getMessage());}finally{try{socket.close();}catch(Exception ignored){}}})).setCancelable(false).show());}catch(Exception e){try{socket.close();}catch(Exception ignored){}}}
 @Override public void onDestroy(){super.onDestroy();try{if(discovery!=null)nsd.stopServiceDiscovery(discovery);}catch(Exception ignored){}try{if(registration!=null)nsd.unregisterService(registration);}catch(Exception ignored){}try{if(server!=null)server.close();}catch(Exception ignored){}if(multicast!=null&&multicast.isHeld())multicast.release();io.shutdownNow();}
